107	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
108	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
109	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
